               if (!missing.isEmpty()) {
                   List<String> missingNames = new ArrayList<>();
                   for (Density d : missing) {
                       missingNames.add(d.getResourceValue());
                   }
                   Collections.sort(missingNames);

                   String message = String.format(
                       "Missing the following drawables in %s-%s: %s (found in %s)",
                       data.folderType.getName(),
                       String.join(", ", missingNames),
                       String.join(", ", missingNames),
                       data.densities.stream().map(Density::getResourceValue).sorted().collect(java.util.stream.Collectors.joining(", "))
