       static {
           EXPECTED_SIZES.put("mdpi", 48);
           EXPECTED_SIZES.put("hdpi", 72);
           EXPECTED_SIZES.put("xhdpi", 96);
           EXPECTED_SIZES.put("xxhdpi", 144);
           EXPECTED_SIZES.put("xxxhdpi", 192);
       }

