       public void visitBinaryResource(@NonNull ResourceContext context) throws IOException {
           File file = context.file;
           String parent = file.getParentFile().getName();
           if (!parent.startsWith("mipmap-") && !parent.startsWith("drawable-")) {
               return;
           }

           String name = file.getName().toLowerCase(Locale.US);
           if (!name.contains("ic_launcher") && !parent.startsWith("mipmap-")) {
