           Integer expected = EXPECTED_SIZES.get(density);
           if (expected == null) return;

           BufferedImage image = ImageIO.read(file);
           if (image == null) return;

           int width = image.getWidth();
           int height = image.getHeight();

           if (width != expected || height != expected) {
               String message = String.format(
                   "Incorrect icon size for `%s`: expected %dx%d, but was %dx%d",
                   density, expected, expected, width, height
               );
               context.report(ISSUE, Location.create(file), message);
           }
       }

       private String extractDensity(String folderName) {
           String[] parts = folderName.split("-");
           for (String part : parts) {
               if (EXPECTED_SIZES.containsKey(part)) {
                   return part;
               }
           }
           return null;
       }
