   class PictureInPictureDetector : Detector(), UastScanner {
       override fun getApplicableMethodNames(): List<String> = listOf("build")

       override fun visitMethodCall(context: JavaContext, node: UCallExpression, method: PsiMethod) {
           val evaluator = context.evaluator
           if (!evaluator.isMemberInClass(method, "android.app.PictureInPictureParams.Builder")) return
           if (context.evaluator.getTargetSdk() < 31) return // Only applies to Android 12+

           val hasAutoEnter = checkBuilderCall(context, node, "setAutoEnterEnabled", true)
           val hasSourceRect = checkBuilderCall(context, node, "setSourceRectHint", null)

           if (!hasAutoEnter || !hasSourceRect) {
               val missing = buildList {
                   if (!hasAutoEnter) add("setAutoEnterEnabled(true)")
                   if (!hasSourceRect) add("setSourceRectHint(...)")
               }
               context.report(
                   ISSUE,
                   node,
                   context.getLocation(node),
                   "Picture-in-Picture transition will be poor quality. Missing: ${missing.joinToString(", ")}"
               )
           }
       }

       private fun checkBuilderCall(context: JavaContext, buildCall: UCallExpression, methodName: String, expectedArg: Boolean?): Boolean {
           val receiver = buildCall.receiver
           val calls = mutableListOf<UCallExpression>()

           when (receiver) {
               is UQualifiedReferenceExpression -> {
                   // Fluent chain: walk up
                   var current: UExpression? = receiver
                   while (current is UQualifiedReferenceExpression) {
                       val selector = current.selector
                       if (selector is UCallExpression) calls.add(selector)
                       current = current.receiver
                   }
                   if (current is UCallExpression) calls.add(current)
               }
               is UReferenceExpression -> {
                   // Variable: find declaration and scan method body
                   val resolved = receiver.resolve()
                   if (resolved is ULocalVariable) {
                       val method = PsiTreeUtil.getParentOfType(resolved, UMethod::class.java)
                       method?.accept(object : AbstractUastVisitor() {
                           override fun visitCallExpression(node: UCallExpression): Boolean {
                               if (node.receiver is UReferenceExpression &&
                                   (node.receiver as UReferenceExpression).resolve() == resolved) {
                                   calls.add(node)
                               }
                               return super.visitCallExpression(node)
                           }
                       })
                   }
               }
           }

           return calls.any { call ->
               call.methodName == methodName && (expectedArg == null || call.valueArguments.getOrNull(0)?.evaluate() == expectedArg)
           }
       }
   }
