   package com.android.tools.lint.checks;

   import com.android.tools.lint.detector.api.*;
   import org.jetbrains.uast.UClass;
   import org.jetbrains.uast.UastModifier;
   import org.w3c.dom.Document;
   import org.w3c.dom.Element;
   import org.w3c.dom.NodeList;

   import java.io.File;
   import java.util.*;

   public class RegistrationDetector extends Detector implements UastScanner {
       // ... ISSUE definition ...
       private final List<Candidate> candidates = new ArrayList<>();

       @Override
       public List<Class<? extends UElement>> getApplicableUastTypes() {
           return Collections.singletonList(UClass.class);
       }

       @Override
       public void visitClass(JavaContext context, UClass node) {
           if (node.hasModifier(UastModifier.ABSTRACT)) return;
           JavaEvaluator evaluator = context.getEvaluator();
           String qn = node.getQualifiedName();
           if (qn == null) return;

           boolean extendsTarget = evaluator.extendsClass(node, "android.app.Activity", false) ||
                                     evaluator.extendsClass(node, "android.app.Service", false) ||
                                     evaluator.extendsClass(node, "android.content.ContentProvider", false);
           if (extendsTarget) {
               candidates.add(new Candidate(qn, context.getLocation(node)));
           }
       }

       @Override
       public void afterCheckProject(Context context) {
           if (candidates.isEmpty()) return;
           File manifest = context.getProject().getManifest();
           if (manifest == null || !manifest.exists()) return;

           Set<String> registered = new HashSet<>();
           try {
               Document doc = XmlUtils.parseDocument(manifest, true);
               Element root = doc.getDocumentElement();
               String pkg = root.getAttribute("package");
               if (pkg == null) pkg = "";

               NodeList appNodes = root.getElementsByTagName("application");
               for (int i = 0; i < appNodes.getLength(); i++) {
                   Element app = (Element) appNodes.item(i);
                   collectComponents(app, "activity", pkg, registered);
                   collectComponents(app, "service", pkg, registered);
                   collectComponents(app, "provider", pkg, registered);
               }
           } catch (Exception e) {
               // Ignore parsing errors
           }

           for (Candidate c : candidates) {
               String name = c.qualifiedName;
               // Normalize for comparison: manifest might use . or $ for inner classes
               String normalized = name.replace('$', '.');
               if (!registered.contains(name) && !registered.contains(normalized)) {
                   context.report(ISSUE, c.location, "Class is not registered in the manifest");
               }
           }
           candidates.clear();
       }

       private void collectComponents(Element parent, String tagName, String pkg, Set<String> registered) {
           NodeList nodes = parent.getElementsByTagName(tagName);
           for (int i = 0; i < nodes.getLength(); i++) {
               Element el = (Element) nodes.item(i);
               String name = el.getAttributeNS(ANDROID_URI, "name");
               if (name != null && !name.isEmpty()) {
                   registered.add(resolveClassName(name, pkg));
               }
           }
       }

       private String resolveClassName(String name, String pkg) {
           if (name.startsWith(".")) {
               return pkg + name;
           } else if (name.indexOf('.') == -1) {
               return pkg + "." + name;
           }
           return name;
       }

       private static class Candidate {
           final String qualifiedName;
           final Location location;
           Candidate(String qn, Location loc) { this.qualifiedName = qn; this.location = loc; }
       }
   }
