   package com.android.tools.lint.checks;

   import com.android.resources.ResourceFolderType;
   import com.android.tools.lint.detector.api.*;
   import org.w3c.dom.Element;
   import org.w3c.dom.NodeList;
   import java.util.*;

   public class ArraySizeDetector extends ResourceXmlDetector {
       // Issue definition
       public static final Issue ISSUE = Issue.create(
           "InconsistentArrays",
           "Inconsistencies in array element counts",
           "When an array is translated in a different locale, it should normally have " +
           "the same number of elements as the original array. When adding or removing " +
           "elements to an array, it is easy to forget to update all the locales, and this " +
           "lint warning finds inconsistencies like these.\n\n" +
           "Note however that there may be cases where you really want to declare a " +
           "different number of array items in each configuration (for example where " +
           "the array represents available options, and those options differ for " +
           "different layout orientations and so on), so use your own judgment to " +
           "decide if this is really an error.\n\n" +
           "You can suppress this error type if it finds false errors in your project.",
           Category.CORRECTNESS,
           5,
           Severity.WARNING,
           new Implementation(ArraySizeDetector.class, Scope.RESOURCE_FILE_SCOPE)
       );

       private Map<String, List<ArrayRecord>> arrayCounts = new HashMap<>();

       private static class ArrayRecord {
           final String name;
           final int count;
           final Location location;
           final String folderName;

           ArrayRecord(String name, int count, Location location, String folderName) {
               this.name = name;
               this.count = count;
               this.location = location;
               this.folderName = folderName;
           }
       }

       @Override
       public boolean appliesTo(ResourceFolderType folderType) {
           return folderType == ResourceFolderType.VALUES;
       }

       @Override
       public Collection<String> getApplicableElements() {
           return Arrays.asList("string-array", "integer-array", "array");
       }

       @Override
       public void visitElement(XmlContext context, Element element) {
           String name = element.getAttribute("name");
           if (name == null || name.isEmpty()) return;

           NodeList items = element.getElementsByTagName("item");
           int count = items.getLength();

           String folderName = context.file.getParentFile().getName();
           Location location = context.getLocation(element);

           arrayCounts.computeIfAbsent(name, k -> new ArrayList<>())
                      .add(new ArrayRecord(name, count, location, folderName));
       }

       @Override
       public void afterCheckProject(Context context) {
           for (Map.Entry<String, List<ArrayRecord>> entry : arrayCounts.entrySet()) {
               List<ArrayRecord> records = entry.getValue();
               if (records.size() < 2) continue;

               // Find base record (from "values" folder)
               ArrayRecord base = null;
               for (ArrayRecord r : records) {
                   if ("values".equals(r.folderName)) {
                       base = r;
                       break;
                   }
               }
               // If no base, use the first one as reference
               if (base == null) {
                   base = records.get(0);
               }

               for (ArrayRecord r : records) {
                   if (r == base) continue;
                   if (r.count != base.count) {
                       String message = String.format(
                           "Array \"%s\" has %d elements in %s but %d elements in %s",
                           r.name, r.count, r.folderName, base.count, base.folderName
                       );
                       context.report(ISSUE, r.location, message);
                   }
               }
           }
       }
   }
