                       }
                   }
               }
           }
           if (!found) {
               context.report(ISSUE, element, context.getLocation(element),
                   "Missing Wear standalone app flag; add <meta-data android:name=\"com.google.android.wearable.standalone\" android:value=\"true|false\"/>");
