               return isContext(evaluator, parameters.get(0).getType());
           } else if (count == 2) {
               return isContext(evaluator, parameters.get(0).getType()) &&
                      isAttributeSet(evaluator, parameters.get(1).getType());
           } else if (count == 3) {
               return isContext(evaluator, parameters.get(0).getType()) &&
