                      evaluator.isInt(parameters.get(2).getType()) &&
                      evaluator.isInt(parameters.get(3).getType());
           }
           return false;
       }

       private boolean isContext(@NonNull JavaEvaluator evaluator, @Nullable PsiType type) {
           return evaluator.typeMatches(type, "android.content.Context");
       }

